from queueing import payload

def submit(owner, enqueue, batch_size=20):
    # Validate integer 1..100, reject bool and invalid values with ValueError BEFORE enqueue
    if isinstance(batch_size, bool):
        raise ValueError('batch_size must not be a boolean')
    if not isinstance(batch_size, int):
        raise ValueError('batch_size must be an integer')
    if batch_size < 1 or batch_size > 100:
        raise ValueError('batch_size must be in range 1..100')
    return enqueue(payload(owner, batch_size))

def execute(task, process):
    # task includes batch_size if present, otherwise default 20
    batch_size = task.get('batch_size', 20)
    # batch_size should already be validated; just use it
    return process(task["owner"], batch_size)

from api import submit
from queueing import payload
from worker import execute

def test_default_batch_size():
    # existing submit(owner, enqueue) should still work
    # simulate enqueue that captures payload
    captured = []
    def enqueue(p):
        captured.append(p)
        return None
    # call without batch_size (default)
    submit('owner1', enqueue)
    # payload should have batch_size=20
    assert captured[0] == {'owner': 'owner1', 'batch_size': 20}

def test_explicit_batch_size():
    captured = []
    def enqueue(p):
        captured.append(p)
        return None
    submit('owner2', enqueue, batch_size=30)
    assert captured[0] == {'owner': 'owner2', 'batch_size': 30}

def test_validation_lower():
    captured = []
    def enqueue(p):
        captured.append(p)
        return None
    try:
        submit('owner3', enqueue, batch_size=0)
        assert False, 'should raise ValueError'
    except ValueError as e:
        assert '1..100' in str(e) or 'must be in range' in str(e)

def test_validation_upper():
    captured = []
    def enqueue(p):
        captured.append(p)
        return None
    try:
        submit('owner4', enqueue, batch_size=101)
        assert False, 'should raise ValueError'
    except ValueError as e:
        assert '1..100' in str(e) or 'must be in range' in str(e)

def test_validation_bool():
    captured = []
    def enqueue(p):
        captured.append(p)
        return None
    try:
        submit('owner5', enqueue, batch_size=True)
        assert False, 'should raise ValueError'
    except ValueError as e:
        assert 'boolean' in str(e).lower()

def test_validation_non_int():
    captured = []
    def enqueue(p):
        captured.append(p)
        return None
    try:
        submit('owner6', enqueue, batch_size='20')
        assert False, 'should raise ValueError'
    except ValueError as e:
        assert 'integer' in str(e).lower()

def test_worker_execute_uses_batch_size():
    # task from payload includes batch_size
    task = {'owner': 'owner7', 'batch_size': 50}
    def dummy_process(owner, bs):
        return f'{owner}:{bs}'
    result = execute(task, dummy_process)
    assert result == 'owner7:50'
    # legacy task without batch_size should default to 20
    task_legacy = {'owner': 'owner8'}
    result2 = execute(task_legacy, dummy_process)
    assert result2 == 'owner8:20'

if __name__ == '__main__':
    test_default_batch_size()
    test_explicit_batch_size()
    test_validation_lower()
    test_validation_upper()
    test_validation_bool()
    test_validation_non_int()
    test_worker_execute_uses_batch_size()
    print('All tests passed')
